import{_ as a,o as s,c as i,a3 as t}from"./chunks/framework.D0WMbOy-.js";const k=JSON.parse('{"title":"Install","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md","lastUpdated":1793490299000}'),n={name:"getting-started/installation.md"};function l(r,e,o,p,h,d){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h1><h2 id="supported-platforms" tabindex="-1">Supported platforms <a class="header-anchor" href="#supported-platforms" aria-label="Permalink to &quot;Supported platforms&quot;">​</a></h2><p>The currently supported targets, each with OpenZFS, are:</p><ul><li>CachyOS;</li><li>Ubuntu 26.04 LTS;</li><li>Ubuntu 26.10.</li></ul><p>Every release is tested on each of them before it is published. The Arch User Repository packages may also work on compatible Arch Linux systems, and the Ubuntu package on other Ubuntu releases and on Debian, but those systems are not currently supported.</p><h2 id="ubuntu" tabindex="-1">Ubuntu <a class="header-anchor" href="#ubuntu" aria-label="Permalink to &quot;Ubuntu&quot;">​</a></h2><p>Install from the Boomerangz apt repository, which carries the latest release for <code>amd64</code> and <code>arm64</code>. The package is the same on every Ubuntu release, so the repository has a single suite, <code>stable</code>.</p><p>Add the repository&#39;s signing key and source, then install:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0755</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/apt/keyrings</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://boomerangz.org/apt/boomerangz-archive-keyring.gpg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/apt/keyrings/boomerangz.gpg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/apt/sources.list.d/boomerangz.sources</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;SOURCES&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Types: deb</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">URIs: https://boomerangz.org/apt</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Suites: stable</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Components: main</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Signed-By: /etc/apt/keyrings/boomerangz.gpg</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SOURCES</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span></span></code></pre></div><p>The package depends on <code>zfsutils-linux</code> and recommends <code>openssh-client</code> for SSH destinations. It installs a static executable, the systemd unit, configuration, restricted SSH login-shell wrapper, manual pages, and shell completions, and creates the <code>boomerangz</code> account. It does not enable or start the service.</p><p>Each release&#39;s <code>.deb</code> files are also attached to its GitHub release and covered by its <code>SHA256SUMS</code>, for installing a specific version with <code>sudo apt install ./boomerangz_&lt;version&gt;_&lt;arch&gt;.deb</code>.</p><h2 id="arch-linux" tabindex="-1">Arch Linux <a class="header-anchor" href="#arch-linux" aria-label="Permalink to &quot;Arch Linux&quot;">​</a></h2><h3 id="choose-a-package" tabindex="-1">Choose a package <a class="header-anchor" href="#choose-a-package" aria-label="Permalink to &quot;Choose a package&quot;">​</a></h3><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-kspe3" id="tab-kw_WwnC" checked><label data-title="Arch Linux / derivatives" for="tab-kw_WwnC">Arch Linux / derivatives</label></div><div class="blocks"><div class="language-text vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>boomerangz      Build from the release source archive</span></span>
<span class="line"><span>boomerangz-bin  Install a prebuilt static binary</span></span></code></pre></div></div></div><p>The packages conflict and install the same executable, systemd unit, configuration, restricted SSH login-shell wrapper, manual pages, and shell completions. The source package builds with CGO disabled and Arch&#39;s PIE hardening. The binary package supports <code>x86_64</code> and <code>aarch64</code>.</p><p>Install one package with your preferred AUR workflow. Always inspect an AUR build recipe before running it.</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-iREpe" id="tab-t1HD9dx" checked><label data-title="Arch Linux / derivatives" for="tab-t1HD9dx">Arch Linux / derivatives</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Example with an installed AUR helper:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paru</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or choose the prebuilt release:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paru</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz-bin</span></span></code></pre></div></div></div><p>Alternatively, download the generated <code>boomerangz-PKGBUILD</code> or <code>boomerangz-bin-PKGBUILD</code> from the matching GitHub release, place it in an empty directory as <code>PKGBUILD</code>, inspect it, and build as your normal user:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-D5sRF" id="tab-lgxn5qB" checked><label data-title="Arch Linux / derivatives" for="tab-lgxn5qB">Arch Linux / derivatives</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">makepkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --syncdeps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span></span></code></pre></div></div></div><p>Release downloads are covered by SHA-256 checksums in both the package recipe and the release&#39;s <code>SHA256SUMS</code> file.</p><h2 id="prepare-the-service" tabindex="-1">Prepare the service <a class="header-anchor" href="#prepare-the-service" aria-label="Permalink to &quot;Prepare the service&quot;">​</a></h2><p>Before starting it:</p><ol><li>configure the required <a href="/development/guide/security#zfs-delegation">ZFS permissions</a>;</li><li>review <code>/etc/boomerangz/config.toml</code>;</li><li>install any <a href="/development/guide/remotes">remote credentials</a> with restrictive permissions;</li><li>validate the merged configuration.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Then continue with <a href="./">Getting started</a>.</p><h2 id="upgrade-or-remove" tabindex="-1">Upgrade or remove <a class="header-anchor" href="#upgrade-or-remove" aria-label="Permalink to &quot;Upgrade or remove&quot;">​</a></h2><p>Upgrade through the same package channel you installed, after reading the <a href="/development/operations/upgrading">upgrade notes</a> for every release between your version and the new one; most need nothing. Preserve the configured <code>identity_dir</code> (by default <code>/var/lib/boomerangz/identity</code>) when upgrading or restoring the same installation; never clone that identity directory to another active host.</p><p>Removing the package does not destroy datasets, snapshots, or replicated data, and neither removing nor purging it removes the <code>boomerangz</code> account or <code>/var/lib/boomerangz</code>, which holds the installation identity. On Ubuntu, <code>apt remove</code> keeps <code>/etc/boomerangz/config.toml</code> and <code>apt purge</code> removes it. Use the preview-first <a href="/development/operations/recovery#explicit-clean">clean procedure</a> before removal only when you intentionally want to retire Boomerangz metadata.</p>`,28)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
